(function(root){'use strict';const C=typeof module!=='undefined'?require('./core.js'):root.Captions,enc=new TextEncoder();
function crc32(bytes){let crc=0xffffffff;for(const b of bytes){crc^=b;for(let j=0;j<8;j++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^0xffffffff)>>>0;}
function zip(files){const parts=[],central=[];let offset=0,centralSize=0;for(const f of files){const name=enc.encode(f.name),data=enc.encode(f.text),crc=crc32(data),head=new Uint8Array(30+name.length),h=new DataView(head.buffer);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint16(12,33,true);h.setUint32(14,crc,true);h.setUint32(18,data.length,true);h.setUint32(22,data.length,true);h.setUint16(26,name.length,true);head.set(name,30);parts.push(head,data);const dir=new Uint8Array(46+name.length),d=new DataView(dir.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint16(14,33,true);d.setUint32(16,crc,true);d.setUint32(20,data.length,true);d.setUint32(24,data.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);dir.set(name,46);central.push(dir);centralSize+=dir.length;offset+=head.length+data.length;}
const end=new Uint8Array(22),d=new DataView(end.buffer);d.setUint32(0,0x06054b50,true);d.setUint16(8,files.length,true);d.setUint16(10,files.length,true);d.setUint32(12,centralSize,true);d.setUint32(16,offset,true);const out=new Uint8Array(offset+centralSize+22);let at=0;for(const part of [...parts,...central,end]){out.set(part,at);at+=part.length;}return out;}
const safeName=(name,i)=>String(i+1).padStart(2,'0')+'-'+(name.normalize('NFC').replace(/[^\p{L}\p{M}\p{N}_-]+/gu,'_').replace(/^_+|_+$/g,'').slice(0,60)||'clip');
const csvCell=x=>'"'+String(x).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';
function prepare(cues,clips,limits){C.validate(cues);C.validateClips(clips);if(!clips.length)throw Error('Add at least one clip to the batch.');const files=[],report=[['Clip','File stem','Source start','Source end','Duration seconds','Caption count','Trimmed boundary captions','Review flags']],rows=[];clips.forEach((p,i)=>{const selected=C.clip(cues,p.start,p.end);if(!selected.length)throw Error('Clip '+(i+1)+' has no captions. Remove it or adjust its range.');const stem=safeName(p.name,i),trimmed=cues.filter(c=>c.end>p.start&&c.start<p.end&&(c.start<p.start||c.end>p.end)).length,flags=C.issues(selected,limits);for(const format of ['srt','vtt'])files.push({name:stem+'.'+format,text:C.serialize(selected,format)});rows.push({name:p.name,stem,count:selected.length,trimmed,flags:flags.length});report.push([p.name,stem,C.stamp(p.start),C.stamp(p.end),(p.end-p.start)/1000,selected.length,trimmed,flags.map(f=>'Caption '+(f.index+1)+': '+f.label).join('; ')]);});files.push({name:'clip-review.csv',text:'\uFEFF'+report.map(r=>r.map(csvCell).join(',')).join('\r\n')});files.push({name:'READ-ME.txt',text:'Caption Desk — batch subtitle delivery\n\nEach SRT and VTT is rebased to its own clip start (00:00). Source ranges are in clip-review.csv. Use exactly those ranges in your video editor.\n\nThe recording is not included or cut. Boundary captions keep their full words but shortened timing: review for cut-off speech. Review flags are prompts, not a publication approval. Check captions against the recording before publishing.\n'});return {files,rows,bytes:zip(files)};}
const api={crc32,zip,prepare,safeName};if(typeof module!=='undefined')module.exports=api;root.CaptionBatch=api;
})(typeof window==='undefined'?globalThis:window);
